from dataclasses import dataclass, field
from typing import Optional, Dict, Any

@dataclass
class SynthesisPayload:
    text: Optional[str] = None
    ssml: Optional[str] = None
    voice_name: str = "en-US-JennyNeural"
    output_format: str = "Audio16Khz32KBitRateMonoMp3"

@dataclass
class TranslationPayload:
    text: str
    from_language: str
    to_language: str

@dataclass
class ContentModerationPayload:
    text: str

@dataclass
class EmbeddingPayload:
    text: str

@dataclass
class TranscriptionPayload:
    audio_bytes: bytes
    audio_format: str = "audio/mpeg"
    language: str = "en-US"

import os
import azure.cognitiveservices.speech as speechsdk
from azure.cognitiveservices.speech import SpeechConfig

def get_speech_config(api_key: str = None, region: str = None) -> SpeechConfig:
    api_key = api_key or os.environ.get("AZURE_SPEECH_KEY")
    region = region or os.environ.get("AZURE_SPEECH_REGION")

    if not api_key or not region:
        raise ValueError("Azure Speech API key and region must be provided or set as environment variables AZURE_SPEECH_KEY and AZURE_SPEECH_REGION.")

    return speechsdk.SpeechConfig(subscription=api_key, region=region)

import azure.cognitiveservices.speech as speechsdk
from speech_client import get_speech_config
from speech_models import SynthesisPayload

def synthesize_ssml(payload: SynthesisPayload, config: dict = None):
    config = config or {}
    speech_config = get_speech_config(api_key=config.get('api_key'), region=config.get('region'))
    speech_config.set_speech_synthesis_output_format(speechsdk.SpeechSynthesisOutputFormat[payload.output_format])

    synthesizer = speechsdk.SpeechSynthesizer(speech_config=speech_config, audio_config=None)
    result = synthesizer.speak_ssml_async(payload.ssml).get()

    if result.reason != speechsdk.ResultReason.SynthesizingAudioCompleted:
        raise RuntimeError(f"Azure SSML synthesis failed: {result.cancellation_details.error_details}")

    return {'audio_bytes': result.audio_data, 'content_type': 'audio/mpeg'}

import os # Used for file operations

def save_audio(audio_bytes: bytes, file_path: str):
    try:
        with open(file_path, 'wb') as audio_file:
            audio_file.write(audio_bytes)
        return {"status": "success", "message": f"Audio saved to {file_path}"}
    except IOError as e:
        raise RuntimeError(f"Failed to save audio to {file_path}: {e}")

import os
import requests
from speech_models import EmbeddingPayload

# Azure OpenAI Embeddings endpoint and key
# https://learn.microsoft.com/en-us/azure/ai-services/openai/reference

def embed_script(payload: EmbeddingPayload, config: dict = None):
    api_key = config.get('api_key') or os.environ.get("AZURE_OPENAI_KEY")
    endpoint = config.get('endpoint') or os.environ.get("AZURE_OPENAI_ENDPOINT")
    deployment_name = config.get('deployment_name') or os.environ.get("AZURE_OPENAI_EMBEDDING_DEPLOYMENT")

    if not api_key or not endpoint or not deployment_name:
        raise ValueError("Azure OpenAI API key, endpoint, and deployment name must be provided or set as environment variables AZURE_OPENAI_KEY, AZURE_OPENAI_ENDPOINT, and AZURE_OPENAI_EMBEDDING_DEPLOYMENT.")

    # Example endpoint: https://YOUR_RESOURCE_NAME.openai.azure.com/
    # Example deployment name: text-embedding-ada-002 (or your custom deployment name)
    url = f"{endpoint}openai/deployments/{deployment_name}/embeddings?api-version=2024-02-01"

    headers = {
        "api-key": api_key,
        "Content-Type": "application/json",
    }

    data = {
        "input": payload.text
    }

    try:
        response = requests.post(url, headers=headers, json=data)
        response.raise_for_status() # Raise an exception for HTTP errors
        embedding_result = response.json()

        if 'data' in embedding_result and len(embedding_result['data']) > 0:
            embedding = embedding_result['data'][0]['embedding']
            return {"embedding": embedding, "model": deployment_name}
        else:
            raise RuntimeError(f"No embedding data found in response: {embedding_result}")

    except requests.exceptions.RequestException as e:
        raise RuntimeError(f"Error calling Azure OpenAI Embeddings API: {e}")
